import { Box } from "@mui/material";
import { useEffect, useState } from "react";
import { ChevronLeft, ChevronRight } from "@mui/icons-material";
import { AnimatePresence, motion } from "framer-motion";

export default function ImageViewport({
    content,
    colors,
    maximized,
    onLoad,
    refreshKey = 0,
    zoomLevel = 1,
    navButtonSize = 40,
}) {
    const [delayedMaximized, setDelayedMaximized] = useState(false);
    const [index, setIndex] = useState(0);
    const [direction, setDirection] = useState(0);

    // falls back to the single imgUrl until content.imgs is populated
    const images =
        content.imgs && content.imgs.length > 0
            ? content.imgs
            : content.imgUrl
              ? [content.imgUrl]
              : [];

    useEffect(() => {
        if (!maximized) {
            setDelayedMaximized(false);
        } else {
            const timer = setTimeout(() => setDelayedMaximized(maximized), 500);
            return () => clearTimeout(timer);
        }
    }, [maximized]);

    // start from the first image whenever the viewport (re)opens or refreshes
    useEffect(() => {
        setIndex(0);
        setDirection(0);
    }, [maximized, refreshKey]);

    const goPrev = () => {
        if (images.length < 2) return;
        setDirection(-1);
        setIndex((prev) => (prev - 1 + images.length) % images.length);
    };

    const goNext = () => {
        if (images.length < 2) return;
        setDirection(1);
        setIndex((prev) => (prev + 1) % images.length);
    };

    const slideVariants = {
        enter: (dir) => ({
            x: dir >= 0 ? "100%" : "-100%",
            opacity: 0,
        }),
        center: {
            x: 0,
            opacity: 1,
        },
        exit: (dir) => ({
            x: dir >= 0 ? "-100%" : "100%",
            opacity: 0,
        }),
    };

    // same treatment as Header / ControlBar: blurred glass, no fill color,
    // sized to a square matching the header's control-bar height
    const navBtnSx = (side) => ({
        flex: `0 0 ${navButtonSize}px`,
        width: navButtonSize,
        height: "100%",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        backdropFilter: "blur(50px)",
        color: colors?.btns || "rgba(150,150,150,1)",
        cursor: "pointer",
        userSelect: "none",
        [side === "left" ? "borderRight" : "borderLeft"]:
            `0.1px solid ${colors?.brd || "rgba(63,63,63,1)"}`,
        transition: "background-color 0.2s ease",
        "&:hover": {
            backgroundColor: "rgba(127,127,127,0.12)",
        },
    });

    return (
        <>
            {!maximized ? (
                <img
                    src={`/img/desktop/${images[index]}`}
                    alt={content.title}
                    draggable={false}
                    onLoad={() => onLoad(true)}
                    style={{
                        width: "100%",
                        height: "100.5%",
                        display: "block",
                        objectFit: "cover",
                    }}
                />
            ) : delayedMaximized ? (
                <Box
                    sx={{
                        width: "100%",
                        height: "100.5%",
                        minHeight: "50vh",
                        overflow: "hidden",
                        display: "flex",
                        flexDirection: "row",
                    }}
                >
                    {images.length > 1 && (
                        <Box
                            onClick={goPrev}
                            role="button"
                            tabIndex={0}
                            aria-label="Previous image"
                            onKeyDown={(e) => {
                                if (e.key === "Enter" || e.key === " ")
                                    goPrev();
                            }}
                            sx={navBtnSx("left")}
                        >
                            <ChevronLeft />
                        </Box>
                    )}

                    <Box
                        sx={{
                            position: "relative",
                            flex: 1,
                            minWidth: 0,
                            height: "100%",
                            overflow: "hidden",
                        }}
                    >
                        <AnimatePresence
                            initial={false}
                            custom={direction}
                        >
                            <motion.img
                                key={index}
                                src={`/img/desktop/${images[index]}`}
                                alt={`${content.title} ${index + 1}`}
                                draggable={false}
                                onLoad={() => onLoad(true)}
                                custom={direction}
                                variants={slideVariants}
                                initial="enter"
                                animate="center"
                                exit="exit"
                                transition={{ duration: 0.35, ease: "easeInOut" }}
                                style={{
                                    position: "absolute",
                                    top: 0,
                                    left: 0,
                                    width: "100%",
                                    height: "100%",
                                    objectFit: "contain",
                                }}
                            />
                        </AnimatePresence>
                    </Box>

                    {images.length > 1 && (
                        <Box
                            onClick={goNext}
                            role="button"
                            tabIndex={0}
                            aria-label="Next image"
                            onKeyDown={(e) => {
                                if (e.key === "Enter" || e.key === " ")
                                    goNext();
                            }}
                            sx={navBtnSx("right")}
                        >
                            <ChevronRight />
                        </Box>
                    )}
                </Box>
            ) : null}
        </>
    );
}
