import { Box, Typography } from "@mui/material";
import { AnimatePresence, motion } from "framer-motion";

import ControlBar from "./ControlBar";
import NavigationBar from "./NavigationBar";

export default function Header({
    type,
    platform,
    colors,
    isMobile,
    maximized,
    setMaximized,
    content,
    active,
    closed,
    setClosed,
    minimized,
    setMinimized,
    onRefresh,
    zoomLevel,
    onZoomIn,
    onZoomOut,
    controlBarRef,
}) {
    const backdropFilter = minimized
        ? "blur(50px) contrast(1.6) saturate(0.3) brightness(0.9)"
        : "blur(50px)";

    return (
        <Box
            sx={{
                backdropFilter: backdropFilter,
                px: minimized || closed ? 2 : "auto",
                py: minimized || closed ? 1 : "auto",
                backgroundColor:
                    closed || (isMobile && active) ? "black" : "auto",
                color:
                    minimized || closed || (isMobile && active)
                        ? "rgba(255, 255, 255, 1)"
                        : // : "rgba(255, 255, 255, 1)",
                          "rgba(50, 50, 50, 1)",
                transition: "all 0.3s ease",
                mixBlendMode: minimized ? "exclusion" : "none",
                borderBottom: true
                    ? `0.01px solid ${colors?.brd || "rgba(63,63,63,1)"}`
                    : "none",
            }}
            className="drag-handle"
        >
            {closed || minimized ? (
                <Typography
                    sx={{
                        fontWeight: 600,
                        letterSpacing: "0.02em",
                    }}
                >
                    {content.title}
                </Typography>
            ) : (
                <>
                    <Box ref={controlBarRef}>
                        <ControlBar
                            platform={platform}
                            colors={colors}
                            setMaximized={setMaximized}
                            setClosed={setClosed}
                            setMinimized={setMinimized}
                        />
                    </Box>

                    {content.type == "web" && (
                        <div
                            style={{
                                position: "relative",
                                overflowY: "hidden",
                                pointerEvents: "auto",
                                maxHeight: maximized ? "100px" : "0px",
                                width: "100%",
                                transition: "all 1s ease-in-out",
                                // borderBottom: `0.1px solid ${colors.brd}`,
                            }}
                        >
                            <NavigationBar
                                content={content}
                                colors={colors}
                                onRefresh={onRefresh}
                                zoomLevel={zoomLevel}
                                onZoomIn={onZoomIn}
                                onZoomOut={onZoomOut}
                            />
                        </div>
                    )}
                </>
            )}
        </Box>
    );
}
